)v(discipline,topic,position,content)
join public.disciplines d on d.name=v.discipline
join public.topics t on t.discipline_id=d.id and t.name=v.topic
join public.materials m on m.topic_id=t.id
where ms.material_id=m.id and ms.position=v.position;

insert into public.material_citations(material_id,source_id,citation_label)
select m.id,s.id,x.label
from (values
 ('Educação do Campo','Resolução CNE/CEB nº 1/2002 — Diretrizes Operacionais para a Educação Básica nas Escolas do Campo','CNE/CEB 1/2002 — Educação do Campo'),
 ('Educação de Jovens e Adultos','Diretrizes Operacionais Nacionais para a Educação de Jovens e Adultos — EJA','MEC/CNE — EJA'),
 ('Educação Ambiental','Resoluções CNE/CP de 2012 — Educação Ambiental','CNE/CP — Educação Ambiental'),
 ('Educação Indígena e Intercultural','Resolução CNE/CEB nº 5/2012 — Diretrizes Curriculares Nacionais para a Educação Escolar Indígena','CNE/CEB 5/2012 — Educação Indígena'),
 ('Educação Indígena e Intercultural','Resolução CNE/CP nº 1, de 15 de maio de 2006 — Diretrizes Curriculares Nacionais para o Curso de Graduação em Pedagogia','DCN Pedagogia')
) x(discipline,source_title,label)
join public.disciplines d on d.name=x.discipline
join public.topics t on t.discipline_id=d.id
join public.materials m on m.topic_id=t.id
join public.sources s on s.title=x.source_title
where not exists(select 1 from public.material_citations mc where mc.material_id=m.id and mc.source_id=s.id);